import{_ as i,l as m,o as t,c as o,v as e,p as h,x as r,d as _,i as n,S as s}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"负任务向量","description":"","frontmatter":{"title":"负任务向量","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/negative-task-vector.md","filePath":"llm/negative-task-vector.md","lastUpdated":1789023840000}'),p={name:"llm/negative-task-vector.md"};function d(c,a,u,E,A,f){const l=m("Mermaid");return t(),o("div",null,[a[1]||(a[1]=e('<h1 id="负任务向量" tabindex="-1">负任务向量 <a class="header-anchor" href="#负任务向量" aria-label="Permalink to &quot;负任务向量&quot;">​</a></h1><div class="epigraph"><p>任务向量是微调后减去微调前的权重差；取负再加回去，等于在权重空间里沿适应方向退回，从而削弱该任务。</p><footer>—— Ilharco 等，Editing Models with Task Arithmetic（ICLR 2023）</footer></div><p><a href="/llm/forgetting-metrics">遗忘的度量</a>给了验收卡。本课用一种不碰 \\(D_f\\) 文本做梯度上升的方法：Ilharco 等人的任务算术。设 \\(\\theta_{\\mathrm{pre}}\\) 为起点，\\(\\theta_t\\) 为在任务 \\(t\\) 上微调后的权重，任务向量 \\(\\tau_t=\\theta_t-\\theta_{\\mathrm{pre}}\\)。推理时 \\(\\theta_{\\mathrm{pre}}+\\tau_t\\) 增强任务；\\(\\theta_{\\mathrm{pre}}-\\lambda\\tau_t\\) 削弱任务。课程「微调、编辑与遗忘」收到这里：适应是一条可加减的方向，负号即遗忘的几何。后课默认会把算术与 <a href="/llm/lora-merge-conflict">LoRA 合并</a>、ROME 槽编辑区分开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>你已经为任务 \\(t\\) 付过一次 SFT（全参或可物化的<a href="/llm/lora">LoRA</a>）。现在要减弱 \\(t\\)（过时技能、误加的风格、需去掉的能力），却不想维护 \\(D_f\\) 做 RMU 或反向梯度。若适应近似沿一条直线，退回去应当削弱 \\(t\\)。问题：\\(\\tau_t\\) 与其它任务是否正交？\\(\\lambda\\gt 1\\) 会不会越过 \\(\\theta_{\\mathrm{pre}}\\) 把通用能力也打负？多任务曾用 \\(\\theta_{\\mathrm{pre}}+\\tau_1+\\tau_2\\) 相加，负号只是其中一项取负——冲突与合并课同源。</p><p>LLM 全参 \\(\\tau\\) 与模型同大，存一份差很贵。LoRA 的 \\(\\tau\\) 就是 \\(\\gamma BA\\)（相对挂载前），负任务向量 = 减去该适配器，几乎免费。若知识在 \\(\\theta_{\\mathrm{pre}}\\) 里而不在 \\(\\tau\\) 里，取负无效：只能削弱「这次微调新增的」，不能削弱预训练先验。这与<a href="/llm/machine-unlearning">遗忘课</a>「LoRA 去不掉预训练知识」一致。</p><h3 id="算术发生在权重空间-不是在梯度上再训" tabindex="-1">算术发生在权重空间，不是在梯度上再训 <a class="header-anchor" href="#算术发生在权重空间-不是在梯度上再训" aria-label="Permalink to &quot;算术发生在权重空间，不是在梯度上再训&quot;">​</a></h3><p>不做优化步。假设微调轨迹的弦 \\(\\tau\\) 近似有用方向。非线性网络里这是启发式；Ortiz-Jimenez 等人讨论在切空间里任务算术更干净，实践仍大量直接加减 \\(\\theta\\)。</p><p><span class="marginnote">Ilharco 原文在 CLIP 与 T5 等模型上展示加技能、减技能、类比组合。解码器 LLM 上同样可做，但 λ 网格必须用遗忘卡，不能假设 λ=1 最优。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>保存 \\(\\theta_{\\mathrm{pre}}\\) 与 \\(\\theta_t\\)（或 LoRA 因子）。选 \\(\\lambda\\) 网格（如 0.3–1.5），构造 \\(\\theta_{\\mathrm{pre}}-\\lambda\\tau_t\\)，在<a href="/llm/forgetting-metrics">遗忘卡</a>上测：任务 \\(t\\) 探针下降、声明的 \\(D_r\\) 效用、格式。<a href="/llm/chat-template">模板</a>必须与训 \\(t\\) 时一致，否则减的是错误条件。多任务：\\(\\theta_{\\mathrm{pre}}+\\sum_i\\sigma_i\\lambda_i\\tau_i\\)，其中 \\(\\sigma_i\\in\\{+1,-1\\}\\)。符号冲突用 TIES 一类修剪，或干脆不要把强负任务与强正相关任务加在同一张网上。</p>',11)),(t(),h(s,null,{default:r(()=>[n(l,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20LR%0A%20%20PRE%5B%22%CE%B8_pre%22%5D%20--%3E%20TAU%5B%22%CF%84%20%3D%20%CE%B8_t%20%E2%88%92%20%CE%B8_pre%22%5D%0A%20%20TAU%20--%3E%20POS%5B%22%CE%B8_pre%20%2B%20%CE%BB%CF%84%20%E5%A2%9E%E5%BC%BA%22%5D%0A%20%20TAU%20--%3E%20NEG%5B%22%CE%B8_pre%20%E2%88%92%20%CE%BB%CF%84%20%E5%89%8A%E5%BC%B1%22%5D%0A%20%20NEG%20--%3E%20CARD%5B%22%E9%81%97%E5%BF%98%E5%8D%A1%E9%AA%8C%E6%94%B6%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[_(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<p>与 ROME 比：任务向量是全局稠密差，不定位槽，副作用按层散开。与 RMU 比：不需要领域语料前向，但必须有一次「正向微调」作为 \\(\\tau\\) 的定义；从未为危险能力专门微调过，就没有该能力的任务向量可减——减一个代理任务（如「回答 WMDP 风格题」的 SFT）只是近似。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>一阶看，\\(\\theta_{\\mathrm{pre}}+\\tau_t\\) 沿微调弦走到终点。负号沿弦反向。若损失在该方向上近似凸且其它任务的梯度与 \\(\\tau_t\\) 内积小，则 \\(t\\) 弱化、其它任务少动。内积大时，负 \\(\\tau_t\\) 等于损坏共享特征，效用栏崩。这就是为何要正交性假设，以及为何<a href="/llm/lora-intrinsic-rank">内在秩</a>低的适应更适合算术：\\(\\tau\\) 能量集中，比较像一条技能轴。</p><p>\\(\\lambda\\gt 1\\) 是外推：可能比 \\(\\theta_{\\mathrm{pre}}\\) 更不会做 \\(t\\)，也可能离开预训练流形。必须靠效用栏截断。LoRA 负向量：\\(-\\gamma BA\\) 加回 \\(W_0\\)，与从未挂载等价当 \\(\\lambda=1\\)；\\(\\lambda\\neq 1\\) 是部分挂载或过校正。</p><p><span class="marginnote">回放是数据空间的折中；负任务向量是权重空间的折中。可以先回放再算术，但难归因。默认选一种主方法。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>没有 \\(\\theta_{\\mathrm{pre}}\\) 或不可物化的适配器，无法做本课。量化后再减，误差累积，应在合并精度上做算术再量化。安全上：负掉「拒答任务向量」会削弱对齐，符号要审查。本课程结束：SFT 工程决定数据与损失；PEFT 决定谁可训练；编辑与遗忘决定如何局部改写或沿任务轴退回。论文附录里的型号对比不插入这条主干。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>任务向量 \\(\\tau_t=\\theta_t-\\theta_{\\mathrm{pre}}\\)；加增强、减削弱。</li><li>只能削弱写在 \\(\\tau_t\\) 里的适应，不能减去预训练先验。</li><li>\\(\\lambda\\) 必须用遗忘卡扫描；\\(\\lambda\\gt 1\\) 是外推。</li><li>多任务加减与 LoRA 合并同一类冲突。</li><li>LoRA 上负向量几乎就是卸载或缩放卸载。</li><li>出处：Ilharco 等，Task Arithmetic，ICLR 2023；度量承接 TOFU / WMDP / 局部性评测。</li></ul>',9))])}const b=i(p,[["render",d]]);export{B as __pageData,b as default};
